<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"><style>table{border-collapse:collapse}th,td{border:1px solid #555;padding:6px}th{font-weight:bold;background:#dbe8f8}.title{font-size:18px;font-weight:bold}</style></head><body><table><tr><td colspan="{{ 10+$subjects->count() }}" class="title">{{ $school?->school_name ?: 'C-Net Pathshala' }}</td></tr><tr><td colspan="{{ 10+$subjects->count() }}">Classwise Result Report | Session: {{ $school?->academic_session ?: '—' }} | Exam: {{ $exam }} | Class: {{ $className }} @if($section)| Section: {{ $section }}@endif</td></tr><tr><td colspan="{{ 10+$subjects->count() }}"></td></tr><tr><th>S.No.</th><th>Roll</th><th>Admission No.</th><th>Student Name</th><th>Section</th>@foreach($subjects as $subject)<th>{{ $subject }}</th>@endforeach<th>Obtained</th><th>Total</th><th>Percentage</th><th>Grade</th><th>Result</th></tr>@foreach($rows as $row)<tr><td>{{ $loop->iteration }}</td><td>{{ $row['student']->roll_no }}</td><td>{{ $row['student']->admission_no }}</td><td>{{ $row['student']->user->name }}</td><td>{{ $row['student']->section }}</td>@foreach($subjects as $subject)@php($r=$row['results']->get($subject))<td>@if($r){{ number_format((float)$r->marks_obtained,2) }}/{{ number_format((float)$r->max_marks,2) }}@endif</td>@endforeach<td>{{ number_format($row['summary']['obtained'],2) }}</td><td>{{ number_format($row['summary']['total'],2) }}</td><td>{{ $row['summary']['percentage'] }}%</td><td>{{ $row['summary']['grade'] }}</td><td>{{ $row['summary']['result'] }}</td></tr>@endforeach</table></body></html>